<?php
// Extract original image streams from supplied PDFs for correspondence branding.
if(PHP_SAPI!=='cli')exit(1);
$root=dirname(__DIR__);$dir=$root.'/var/qa/extracted';if(!is_dir($dir))mkdir($dir,0700,true);$pdf=file_get_contents($root.'/samples/EDDT Demand Notice.pdf');preg_match_all('/(\d+)\s+0\s+obj\s*(.*?)endobj/s',$pdf,$objects,PREG_SET_ORDER);
foreach($objects as $obj){$body=$obj[2];$pos=strpos($body,'stream');if($pos===false)continue;$dict=substr($body,0,$pos);if(!preg_match('#/Subtype\s*/Image#',$dict))continue;echo $obj[1].' '.preg_replace('/\s+/',' ',$dict)."\n";$start=$pos+6;if(substr($body,$start,2)==="\r\n")$start+=2;elseif(substr($body,$start,1)==="\n")$start++;$end=strrpos($body,'endstream');$stream=substr($body,$start,$end-$start);if(preg_match('#/Length\s+(\d+)\s*/#',$dict,$m))$stream=substr($stream,0,(int)$m[1]);if(str_contains($dict,'DCTDecode'))file_put_contents($dir.'/image-'.$obj[1].'.jpg',$stream);elseif(str_contains($dict,'FlateDecode')){preg_match('#/Width\s+(\d+)#',$dict,$w);preg_match('#/Height\s+(\d+)#',$dict,$h);$data=@gzuncompress($stream);if($data!==false&&isset($w[1],$h[1])){echo 'Decoded bytes '.strlen($data)."\n";if(strlen($data)==$w[1]*$h[1]*3){$img=imagecreatetruecolor((int)$w[1],(int)$h[1]);$i=0;for($y=0;$y<$h[1];$y++)for($x=0;$x<$w[1];$x++){imagesetpixel($img,$x,$y,(ord($data[$i++])<<16)|(ord($data[$i++])<<8)|ord($data[$i++]));}imagepng($img,$dir.'/image-'.$obj[1].'.png');imagedestroy($img);}}}}
